* { box-sizing: border-box; }
:root { color-scheme: dark; font-family: system-ui, -apple-system, "Segoe UI", sans-serif; color: #f4f0ff; background: #17192d; }
body { min-height: 100vh; margin: 0; padding: 32px 16px; display: grid; place-items: center; background: radial-gradient(ellipse at 50% 0%, #303354 0, #17192d 64%); font-size: 16px; }
.card { width: min(100%, 520px); padding: 30px; border: 2px solid #484b70; border-radius: 18px; background: #22243c; box-shadow: 0 18px 60px #0b0c18aa; }
.header { display: flex; align-items: center; gap: 16px; }
.brand-mark { width: 54px; height: 54px; display: grid; place-items: center; border: 2px solid #8ee6ca; border-radius: 12px; background: #303354; color: #8ee6ca; font-size: 32px; box-shadow: 4px 4px 0 #111326; }
.eyebrow, .summary-label { margin: 0; color: #aaaed0; font-size: 12px; font-weight: 800; letter-spacing: .12em; }
h1 { margin: 3px 0 0; font-size: clamp(25px, 7vw, 32px); line-height: 1.15; }
.summary { display: flex; justify-content: space-between; gap: 12px; margin: 26px 0 28px; padding: 17px 19px; border: 1px solid #484b70; border-radius: 12px; background: #1b1d32; }
.summary > div { display: grid; gap: 5px; }
.summary > div:last-child { text-align: right; }
.summary strong { font-size: 19px; font-variant-numeric: tabular-nums; }
.list-heading { display: flex; align-items: center; justify-content: space-between; margin-bottom: 12px; }
h2 { margin: 0; font-size: 18px; }
.pixel-dot { width: 10px; height: 10px; background: #8ee6ca; box-shadow: 4px 0 #8ee6ca, 0 4px #8ee6ca, 4px 4px #8ee6ca; }
.playlist { display: grid; gap: 9px; margin: 0; padding: 0; list-style: none; }
.track { min-width: 0; display: grid; grid-template-columns: 38px minmax(0, 1fr) auto; align-items: center; gap: 12px; padding: 11px 12px; border: 1px solid #3d405f; border-radius: 11px; background: #292b46; }
.track-number { color: #aaaed0; font-size: 14px; font-variant-numeric: tabular-nums; }
.track-copy { min-width: 0; }
.track-title { overflow: hidden; color: #f4f0ff; font-weight: 700; text-overflow: ellipsis; white-space: nowrap; }
.track-artist { margin-top: 2px; color: #aaaed0; font-size: 14px; }
.track-duration { color: #d8d4ec; font-size: 14px; font-variant-numeric: tabular-nums; }
.track-actions { grid-column: 1 / -1; display: flex; justify-content: flex-end; gap: 7px; margin-top: 2px; }
button { min-height: 40px; padding: 7px 11px; border: 1px solid #66698d; border-radius: 8px; background: #303354; color: #f4f0ff; font: inherit; font-size: 14px; font-weight: 650; cursor: pointer; transition: background .15s, transform .1s, border-color .15s; }
button:hover:not(:disabled) { border-color: #8ee6ca; background: #3b3e61; }
button:focus-visible { outline: 3px solid #8ee6ca; outline-offset: 3px; }
button:active:not(:disabled) { transform: translateY(2px); }
button:disabled { opacity: .4; cursor: not-allowed; }
.remove-button { color: #ffd1c9; }
.shuffle-button { width: 100%; min-height: 50px; margin-top: 20px; border-color: #8ee6ca; background: #8ee6ca; color: #17192d; font-size: 16px; }
.shuffle-button:hover { background: #a9f3dc !important; color: #17192d; }
.shuffle-button span { margin-right: 7px; font-size: 22px; vertical-align: -2px; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }
@media (min-width: 460px) { .track { grid-template-columns: 34px minmax(0, 1fr) auto auto; } .track-actions { grid-column: auto; margin: 0; } }
@media (max-width: 400px) { .card { padding: 22px 18px; } .summary { padding: 14px; } .summary strong { font-size: 17px; } }

const songs = [
  { title: "Neon Rooftops", artist: "Chiptune Arcade", seconds: 187 },
  { title: "Moonlit Circuit", artist: "Bitwave", seconds: 243 },
  { title: "Save Point Sunrise", artist: "Tiny Quest", seconds: 156 },
  { title: "Crystal Caverns", artist: "8-Bit Wanderer", seconds: 212 },
  { title: "Last Level Lullaby", artist: "Pixel Pilot", seconds: 278 },
  { title: "Bonus Stage", artist: "Coin Drop Kids", seconds: 194 }
];
let playlist = [...songs];
const list = document.querySelector("#playlist");
const count = document.querySelector("#song-count");
const total = document.querySelector("#total-time");
const status = document.querySelector("#status");

function formatTime(seconds) {
  const hours = Math.floor(seconds / 3600);
  const minutes = Math.floor((seconds % 3600) / 60);
  const remaining = seconds % 60;
  return `${hours}:${String(minutes).padStart(2, "0")}:${String(remaining).padStart(2, "0")}`;
}

function render() {
  list.replaceChildren();
  playlist.forEach((song, index) => {
    const item = document.createElement("li");
    item.className = "track";
    const number = document.createElement("span");
    number.className = "track-number";
    number.textContent = `#${String(index + 1).padStart(2, "0")}`;
    const copy = document.createElement("div");
    copy.className = "track-copy";
    const title = document.createElement("div");
    title.className = "track-title";
    title.textContent = song.title;
    const artist = document.createElement("div");
    artist.className = "track-artist";
    artist.textContent = song.artist;
    copy.append(title, artist);
    const duration = document.createElement("span");
    duration.className = "track-duration";
    duration.textContent = formatTime(song.seconds);
    const actions = document.createElement("div");
    actions.className = "track-actions";
    const up = makeButton("↑ Move up", index === 0, () => move(index, -1));
    const down = makeButton("↓ Move down", index === playlist.length - 1, () => move(index, 1));
    const remove = makeButton("Remove", false, () => {
      const [removed] = playlist.splice(index, 1);
      render();
      status.textContent = `${removed.title} removed.`;
    });
    remove.classList.add("remove-button");
    actions.append(up, down, remove);
    item.append(number, copy, duration, actions);
    list.append(item);
  });
  count.textContent = `${playlist.length} ${playlist.length === 1 ? "song" : "songs"}`;
  total.textContent = formatTime(playlist.reduce((sum, song) => sum + song.seconds, 0));
}

function makeButton(label, disabled, action) {
  const button = document.createElement("button");
  button.type = "button";
  button.textContent = label;
  button.setAttribute("aria-label", label);
  button.disabled = disabled;
  button.addEventListener("click", action);
  return button;
}

function move(index, offset) {
  const target = index + offset;
  [playlist[index], playlist[target]] = [playlist[target], playlist[index]];
  render();
  status.textContent = `${playlist[target].title} moved ${offset < 0 ? "up" : "down"}.`;
}

document.querySelector("#shuffle-button").addEventListener("click", () => {
  for (let i = playlist.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [playlist[i], playlist[j]] = [playlist[j], playlist[i]];
  }
  render();
  status.textContent = "Playlist shuffled.";
});

render();
